 Object.entries(PERF).forEach(([k,v])=>{if(!Array.isArray(v.v)||k==='DAF')return;v.v.push('dafval');if(k==='Fiel de armazém')v.v.push('dafguias');if(k==='Compras')v.v.push('dafaturas','dafrast','dafarq')});
