const MO={AOA:'Kz',USD:'USD',EUR:'EUR'},mf=(v,f)=>v===''||v==null||isNaN(v)?'—':Number(v).toLocaleString('pt-PT',{minimumFractionDigits:2,maximumFractionDigits:2})+' '+(MO[(f&&f.moeda)||'AOA']||'Kz'),tkz=f=>(+f.total||0)*((f.moeda&&f.moeda!=='AOA'?+f.cambio:1)||1);
