const nextGuia=()=>{const y=today().slice(0,4),n=A().filter(f=>f.guia&&f.guia.numero&&f.guia.numero.startsWith('GE-'+y)).reduce((m,f)=>Math.max(m,+f.guia.numero.split('-').pop()||0),0)+1;return 'GE-'+y+'-'+String(n).padStart(4,'0')};
