function arqList(){const all=A().filter(x=>x.estado===EST[3]||x.estado===EST[4]).sort((a,b)=>((b.prim||{}).data||b.desde||'').localeCompare((a.prim||{}).data||a.desde||'')),y=st.dafy||'',m=st.dafm||'',fo=st.daffo||'';return{all,l:all.filter(x=>(!y||(x.data||'').slice(0,4)===y)&&(!m||(x.data||'').slice(5,7)===m)&&(!fo||x.fornecedor===fo))}}
